(async()=>{
 const {startVitest}=await import('vitest/node');
 const {createHash}=await import('node:crypto');
 const config=CONFIG;
 let applied=0,summary;
 const ctx=await startVitest(config.tests,{run:true,maxWorkers:1,reporters:[{onTestRunEnd(modules,errors,reason){
  const ts=modules.flatMap(m=>[...m.children.allTests()]);
  summary={reason,total:ts.length,passed:ts.filter(t=>t.result().state==='passed').length,failed:ts.filter(t=>t.result().state==='failed').map(t=>t.fullName),errors:errors.map(e=>e.message)};
 }}]},{plugins:[{name:'repair-in-memory-mutation',enforce:'pre',transform(code,id){
  if(!id.replaceAll('\\','/').endsWith('/'+config.file))return;
  const count=code.split(config.before).length-1;
  if(count!==1)throw Error('MUTATION_NOT_APPLIED '+count);
  const changed=code.replace(config.before,config.after);applied++;
  console.log(JSON.stringify({id:config.id,applied,sourceHash:createHash('sha256').update(code).digest('hex'),mutantHash:createHash('sha256').update(changed).digest('hex')}));
  return {code:changed,map:null};
 }}]});
 await ctx.close();console.log(JSON.stringify({id:config.id,applied,...summary}));
 if(applied!==1||!summary||summary.errors.length)process.exitCode=2;
})().catch(e=>{console.error(e);process.exitCode=2});

