coarsePerformance.script:
import { performance } from 'node:perf_hooks';
import { kernel, registerTask, registerContract, decide, contractText, metadata, hashOf } from './tests/forge/fixtures.ts';
import { evaluateVerification } from './src/forge/verification.ts';
import { VerificationEvidenceSchema } from './src/forge/runs.ts';
const events=[];
for(let i=1;i<=150;i++) {
 const taskId='TASK-'+String(i).padStart(4,'0'), t=contractText(metadata({taskId}));
 events.push(registerTask(taskId),registerContract(t,{taskId}),decide(hashOf(t),'approved',{taskId}));
}
const meta={scope:{create:['src/a.ts'],modify:[]},requiredChecks:[{name:'test',command:'npm test'}],mutationSmoke:'none'};
const evidence={runId:'run:bench',verifiedCommit:'1'.repeat(40),method:'fresh_clone',changedFiles:[{path:'src/a.ts',change:'added'}],checks:[{name:'test',command:'npm test',exitCode:0}],mutations:null};
const samples=[];
for(let n=0;n<4;n++){
 let t=performance.now(); const replay=kernel.replay(events);
 if(!replay.ok||replay.state.log.length!==450)throw Error('replay');
 const replayMs=performance.now()-t;t=performance.now();
 for(let i=0;i<10000;i++){ const parsed=VerificationEvidenceSchema.parse(evidence); if(!evaluateVerification(meta,{mutations:[]},parsed).passed)throw Error('verify'); }
 const verifyMs=performance.now()-t;if(n>0)samples.push({replayMs,verifyMs});
}
console.log(JSON.stringify({events:450,verificationsPerSample:10000,warmups:1,samples,medianReplayMs:[...samples.map(x=>x.replayMs)].sort((a,b)=>a-b)[1],medianVerifyMs:[...samples.map(x=>x.verifyMs)].sort((a,b)=>a-b)[1]}));
